        mapper.disable(ToXmlGenerator.Feature.IGNORE_UNDEFINED);

        final byte[] xmlBytes = XML.getBytes("UTF-8");
        final byte[] xmlBytesWithArray = XML_WITH_ARRAY.getBytes("UTF-8");

